//! Demo files for development: real images and videos generated by
//! `dev/make-demo.sh`, placed into the fake index under their own paths.
//!
//! Previews are only ever made for files below [`demo_dir`]. Nothing else on
//! the machine is opened, so fake paths that happen to exist on the real
//! file system stay untouched.

use std::{
    path::{Path, PathBuf},
    sync::atomic::{AtomicBool, Ordering},
};

use anything_core::RealEntry;

/// Whether the fake index is in use (`ANYTHING_DEMO=1`, or benchmarks).
static DEMO_MODE: AtomicBool = AtomicBool::new(false);

pub fn set_demo_mode(on: bool) {
    DEMO_MODE.store(on, Ordering::Relaxed);
}

pub fn demo_mode() -> bool {
    DEMO_MODE.load(Ordering::Relaxed)
}

pub fn demo_dir() -> PathBuf {
    crate::settings::repo_dir().join("dev").join("demo")
}

/// Whether previews may be made for `path`. With the fake index only the
/// demo files are real; nothing else may be opened to make a preview.
pub fn may_preview(path: &Path) -> bool {
    !demo_mode() || path.starts_with(demo_dir())
}

/// Whether `path` may be opened. With the fake index only the demo files are
/// real; everything else exists only there, even if the same path happens to
/// exist on this machine.
pub fn may_open(path: &Path) -> bool {
    !demo_mode() || path.starts_with(demo_dir())
}

/// Every file and folder below the demo folder. Empty when it was not
/// generated yet.
pub fn entries() -> Vec<RealEntry> {
    let mut found = Vec::new();
    let root = demo_dir();
    if root.is_dir() {
        walk(&root, &mut found);
        if let Some(entry) = entry(&root, true) {
            found.push(entry);
        }
    }
    found
}

fn walk(dir: &Path, found: &mut Vec<RealEntry>) {
    let Ok(read) = std::fs::read_dir(dir) else { return };
    for item in read.flatten() {
        let path = item.path();
        let Ok(kind) = item.file_type() else { continue };
        if kind.is_dir() {
            if let Some(e) = entry(&path, true) {
                found.push(e);
            }
            walk(&path, found);
        } else if kind.is_file()
            && let Some(e) = entry(&path, false)
        {
            found.push(e);
        }
    }
}

fn entry(path: &Path, is_dir: bool) -> Option<RealEntry> {
    let meta = std::fs::metadata(path).ok()?;
    let mtime = meta
        .modified()
        .ok()?
        .duration_since(std::time::UNIX_EPOCH)
        .ok()?
        .as_secs() as i64;
    Some(RealEntry {
        path: path.to_str()?.to_owned(),
        is_dir,
        size: if is_dir { 0 } else { meta.len() },
        mtime,
    })
}
